-- SOLO PG17 DESCARTABLE: reproduce fuente saly.reglas y autoridades SALY con snapshots verificados.
-- Nunca aplicar en Supabase real; PASE usa --network none. 
BEGIN;
DO $t$ BEGIN IF (SELECT count(*) FROM saly.reglas)<>14 OR (SELECT count(*) FROM saly.decisiones)<>8 THEN RAISE EXCEPTION 'SALY_PG17_SEED_BAD'; END IF; END $t$;
COMMIT;
