INSERT INTO saly.reglas(id,codigo,categoria,titulo,regla,razon,alcance,producto_codigo,valor_config,parametrizable,es_transversal,estado,vigente,decision_id,fuente,metadata) OVERRIDING SYSTEM VALUE VALUES
(1,'SALY-RGL-001','MOTOR_DISPONIBLE','Curvas core del motor','El motor admite LINEAR, STEPS e INSTANT. INSTANT equivale a STEPS con liberación 100%.','Evita motores específicos por empresa o periodicidad.','PRODUCTO','ADELANTO','{"curve_types":["LINEAR","STEPS","INSTANT"]}'::jsonb,true,false,'VALIDADO',true,51,'Motor Disponible V2.3','{"version":"V2.3"}'::jsonb),
(2,'SALY-RGL-002','MOTOR_DISPONIBLE','Assignment cap','assignment_cap limita la base antes del devengo y puede expresarse como porcentaje y/o monto.','Distingue la elegibilidad inicial del límite de acumulación o retiro.','PRODUCTO','ADELANTO','{"pct_default":1,"amount_default":null}'::jsonb,true,false,'VALIDADO',true,53,'Motor Disponible V2.3','{"version":"V2.3"}'::jsonb),
(3,'SALY-RGL-003','MOTOR_DISPONIBLE','Accrual cap','accrual_cap limita el monto máximo que puede alcanzar el devengado sin alterar la base.','Representa casos de acumulación diaria hasta un máximo.','PRODUCTO','ADELANTO','{}'::jsonb,true,false,'VALIDADO',true,53,'Motor Disponible V2.3','{"version":"V2.3"}'::jsonb),
(4,'SALY-RGL-004','MOTOR_DISPONIBLE','Withdrawal limits','Los límites de retiro se aplican después del saldo disponible y no modifican el saldo generado.','Permite max por operación, ciclo, número de operaciones y mínimo.','PRODUCTO','ADELANTO','{"max_per_cycle":null,"max_operations":null,"max_per_operation":null,"min_per_operation":null}'::jsonb,true,false,'VALIDADO',true,53,'Motor Disponible V2.3','{"version":"V2.3"}'::jsonb),
(5,'SALY-RGL-005','CALENDARIO','Ciclo materializado','El cálculo debe referenciar un ciclo materializado; semanal, quincenal y mensual no son fórmulas del motor.','Evita ambigüedad en fechas, meses y múltiples cortes.','PRODUCTO','ADELANTO','{"on_missing_day":"LAST_DAY","config_change_default":"NEXT_CYCLE"}'::jsonb,true,false,'VALIDADO',true,54,'Motor Disponible V2.3','{"version":"V2.3"}'::jsonb),
(6,'SALY-RGL-006','MOTOR_DISPONIBLE','Gate de disposición','Una ventana puede bloquear disposición sin detener la acumulación.','Representa cierres/bloqueos operativos sin perder saldo generado.','PRODUCTO','ADELANTO','{"blocks_accrual":false,"blocks_disposal":true}'::jsonb,true,false,'VALIDADO',true,55,'Motor Disponible V2.3','{"version":"V2.3"}'::jsonb),
(7,'SALY-RGL-007','MOTOR_DISPONIBLE','Excepción temporal de bloqueo','Un colaborador puede recibir permiso temporal para retirar durante un bloqueo de disposición; la excepción no altera la fórmula ni la configuración general.','Cubre excepciones solicitadas por empresa u operación sin crear fórmulas especiales.','EMPLEADO','ADELANTO','{"type":"TEMPORARY_DISPOSAL_ALLOW","auditable":true,"requires_reason":true,"requires_validity":true}'::jsonb,true,false,'VALIDADO',true,55,'Motor Disponible V2.3','{"version":"V2.3"}'::jsonb),
(8,'SALY-RGL-008','MOTOR_DISPONIBLE','Saldo adicional temporal','El saldo adicional extraordinario se otorga a un colaborador por ciclo o vigencia; no modifica la configuración normal, el remanente vence por defecto y por defecto sigue el gate de disposición general.','Permite autorizaciones puntuales sin contaminar la base recurrente.','EMPLEADO','ADELANTO','{"scope":"EMPLOYEE","temporary":true,"carry_over_default":false,"follows_disposal_gate":true,"consumption_priority_default":"EXTRA_FIRST_BY_EXPIRY"}'::jsonb,true,false,'VALIDADO',true,56,'Motor Disponible V2.3','{"version":"V2.3"}'::jsonb),
(9,'SALY-RGL-009','MOTOR_DISPONIBLE','Fuente VARIABLE_UPLOAD','VARIABLE_UPLOAD es una fuente normal de base por empleado y ciclo para comisiones, bonos u otros variables. Cuando aplica, sueldo y porcentaje salarial no intervienen.','Elimina el workaround histórico de porcentaje cero + excepción.','PRODUCTO','ADELANTO','{"concepts":["COMMISSION","BONUS","VARIABLE_PAY","OTHER"],"correction_mode":"ADJUSTMENT_EVENT","carry_over_default":false,"idempotency_required":true,"batch_scoped_to_cycle":true,"missing_employee_default_amount":0}'::jsonb,true,false,'VALIDADO',true,57,'Motor Disponible V2.3','{"version":"V2.3"}'::jsonb),
(10,'SALY-RGL-010','MOTOR_DISPONIBLE','Corrección de carga variable','Las correcciones de VARIABLE_UPLOAD no sobrescriben historia; deben registrarse como versión/movimiento correctivo y preservar consumos ya ocurridos.','Evita que una corrección retroactiva cambie artificialmente el pasado.','PRODUCTO','ADELANTO','{"correction_mode":"ADJUSTMENT_EVENT","overwrite_history":false}'::jsonb,true,false,'VALIDADO',true,57,'Motor Disponible V2.3','{"version":"V2.3"}'::jsonb),
(11,'SALY-RGL-011','GOBERNANZA','Redondeo monetario','No usar float ni redondeos intermedios; redondear con floor solo al resultado final y aplicar clamp mayor o igual a cero.','Evita errores acumulados en ciclos de distinta longitud.','TRANSVERSAL',NULL,'{"rounding":"FLOOR_FINAL_ONLY","clamp_min":0}'::jsonb,false,true,'VALIDADO',true,58,'Motor Disponible V2.3','{"version":"V2.3"}'::jsonb),
(12,'SALY-RGL-012','GOBERNANZA','Traza de cálculo','Cada cálculo de disponible debe poder reconstruirse con as_of, employee, cycle, config_version, config_hash, engine_version, base, caps, gates, consumos, reservas, resultado y trace.','Garantiza auditoría, soporte y explicabilidad.','TRANSVERSAL',NULL,'{}'::jsonb,false,true,'VALIDADO',true,58,'Motor Disponible V2.3','{"version":"V2.3"}'::jsonb),
(13,'SALY-RGL-013','GOBERNANZA','Autorización de excepciones y saldos extraordinarios','Excepciones de bloqueo y saldos extraordinarios pueden ser creados por operador de plataforma o empresa únicamente cuando exista permission_code explícito; se debe persistir actor, alcance, motivo y evidencia de autorización.','Evitar que la capacidad de alterar temporalmente el disponible se derive de nombres de rol o de acceso implícito.','PRODUCTO','ADELANTO','{"creator_scopes":["PLATFORM","COMPANY"],"requires_audit":true,"requires_reason":true,"requires_permission":true}'::jsonb,true,false,'VALIDADO',true,56,'chat V2.3','{"version":"V2.3"}'::jsonb),
(14,'SALY-RGL-014','MOTOR_DISPONIBLE','Saly Plus — adelanto temporal de disponibilidad','Si el beneficio Saly Plus está activo, anticipation_days=N adelanta temporalmente la disponibilidad correspondiente sin aumentar assignment_cap, accrual_cap ni el máximo total del período. Conceptualmente: disponible_base_plus(t)=min(disponible_base_estandar(t+N días), maximo_asignado_del_periodo). Después se aplican retiros, reservas, withdrawal_limits, gates, bloqueos y excepciones vigentes.','El beneficio comercial debe mejorar acceso temporal sin deteriorar el control de exposición ni crear saldo adicional.','PRODUCTO','ADELANTO','{"active":null,"valid_to":null,"plan_code":null,"anchor_ref":null,"exceptions":[],"valid_from":null,"anchor_type":null,"curve_types":["LINEAR","STEPS","INSTANT"],"product_code":"ADELANTO","company_scope":[],"day_count_type":null,"conflict_policy":"MOST_RESTRICTIVE_WINS","membership_code":null,"time_shift_only":true,"anticipation_days":null,"increases_period_cap":false,"block_override_policy":"NO_OVERRIDE"}'::jsonb,true,false,'VALIDADO',true,60,'SALY_PLUS_ACCESO_ANTICIPADO_V1.0 / aprobación en chat','{"version":"V1.0","benefit_code":"SALY_PLUS_EARLY_ACCESS","drive_file_id":"1XJevht7bZXMGSDGq-0dYkXEwRMUNWAl7FxwGy2JrU2M","commercial_examples_days":[3,5]}'::jsonb);
